import React, { useEffect, useState } from "react";
import { Accordion, AccordionSummary, AccordionDetails, Typography, Link, Checkbox } from "@mui/material";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import { fetchDataFromApi } from "../utils/api";

export default function SubjectsTopics() {
  const [subjects, setSubjects] = useState([]);

  useEffect(() => {
    fetchDataFromApi("/subject/get").then((res)=>{
        console.log(res)
        setSubjects(res.data)
    })
  }, []);

  return (
    <div>
      {Array.isArray(subjects) &&
      subjects?.map(subject => (
        <Accordion key={subject._id}>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography variant="h6">{subject.name}</Typography>
          </AccordionSummary>
          <AccordionDetails>
            {subject.topics.map(topic => (
              <div key={topic._id} style={{ marginBottom: "10px" }}>
                <Checkbox checked={topic.status === "Done"} />
                <strong>{topic.name}</strong> - {topic.level}
                <div>
                  <Link href={topic.leetcode} target="_blank" rel="noopener">LeetCode</Link> |{" "}
                  <Link href={topic.youtube} target="_blank" rel="noopener">YouTube</Link> |{" "}
                  <Link href={topic.article} target="_blank" rel="noopener">Article</Link>
                </div>
              </div>
            ))}
          </AccordionDetails>
        </Accordion>
      ))}
    </div>
  );
}
